  function escHtml(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function pickLang() {
    var params = new URLSearchParams(window.location.search);
    if (params.has('lang') && I18N[params.get('lang')]) { return params.get('lang'); }
    var nav = (navigator.language || 'en');
    if (/^zh/i.test(nav)) { return 'zh-TW'; }
    var short = nav.slice(0, 2).toLowerCase();
    if (I18N[short]) { return short; }
    return 'en';
  }

  var currentLang = pickLang();

  function buildLangSelect() {
    var sel = document.getElementById('lang-select');
    sel.innerHTML = '';
    Object.keys(I18N).forEach(function (key) {
      var opt = document.createElement('option');
      opt.value = key;
      opt.textContent = I18N[key].name;
      if (key === currentLang) { opt.selected = true; }
      sel.appendChild(opt);
    });
  }

  function sectionsFor(t) {
    return [
      { id: 'sec-tools',   icon: 'tools',   color: '#4f46e5', title: t.toolsTitle },
      { id: 'sec-apis',    icon: 'api',     color: '#0284c7', title: t.apisTitle },
      { id: 'sec-install', icon: 'install', color: '#f59e0b', title: t.installTitle },
      { id: 'sec-note',    icon: 'shield',  color: '#dc2626', title: t.noteTitle }
    ];
  }

  function toolsTableHtml(t) {
    var rows = '';
    DATA.tools.forEach(function (tool) {
      rows += '<tr><td><strong>' + escHtml(tool.name) + '</strong></td><td><code>' + escHtml(tool.entry) + '</code></td></tr>';
    });
    return '<table><thead><tr><th style="width:38%">' + escHtml(t.colTool) + '</th><th>' + escHtml(t.colEntry) + '</th></tr></thead><tbody>' + rows + '</tbody></table>';
  }

  function apisTableHtml(t) {
    var rows = '';
    DATA.apis.forEach(function (api) {
      var enc = (api.enc && api.enc !== '無') ? api.enc : '';
      var encTag = enc ? '<span class="enc-tag">' + escHtml(enc) + '</span>' : '<span class="enc-tag none">-</span>';
      rows += '<tr><td><strong>' + escHtml(api.title) + '</strong></td><td>' + encTag + '</td><td>' + escHtml(api.desc || '') + '</td></tr>';
    });
    if (!rows) { rows = '<tr><td colspan="3" style="color:#9ca3af">-</td></tr>'; }
    return '<table><thead><tr><th>' + escHtml(t.colApi) + '</th><th style="width:22%">' + escHtml(t.colEnc) + '</th><th>' + escHtml(t.colDesc) + '</th></tr></thead><tbody>' + rows + '</tbody></table>';
  }

  function stepsHtml(t) {
    var items = '';
    t.installSteps.forEach(function (step) {
      items += '<li>' + escHtml(step.replace(/\{slug\}/g, DATA.slug)) + '</li>';
    });
    return '<ol class="steps">' + items + '</ol>';
  }

  function navLink(target, iconKey, label) {
    return '<a href="#' + target + '" class="nav-link" data-target="' + target + '" onclick="onNav()"><span class="nav-ico">' + ICONS[iconKey] + '</span><span>' + escHtml(label) + '</span></a>';
  }

  function render() {
    var t = I18N[currentLang] || I18N.en;
    var langMap = { 'zh-TW': 'zh-Hant', 'en': 'en', 'ja': 'ja', 'ko': 'ko' };
    document.documentElement.lang = langMap[currentLang] || 'en';
    document.title = DATA.sysLabel + ' - ' + t.brand;

    document.getElementById('brand-title').textContent  = t.brand;
    document.getElementById('brand-system').textContent = DATA.sysLabel;
    document.getElementById('m-title').textContent      = t.brand;
    document.getElementById('foot-system').textContent  = DATA.sysLabel;

    var secs = sectionsFor(t);

    var navHtml = navLink('hero', 'download', t.downloadBtn);
    secs.forEach(function (sec) { navHtml += navLink(sec.id, sec.icon, sec.title); });
    document.getElementById('nav-links').innerHTML = navHtml;

    var html = ''
      + '<section id="hero" class="hero">'
      +   '<div class="hero-wm">' + ICONS.robot + '</div>'
      +   '<h1>' + escHtml(DATA.sysLabel) + ' - ' + escHtml(t.brand) + '</h1>'
      +   '<p>' + escHtml(t.heroDesc.replace('{sys}', DATA.sysLabel)) + '</p>'
      +   '<button class="btn-dl" type="button" onclick="downloadPack()">' + ICONS.download + '<span>' + escHtml(t.downloadBtn) + '</span></button>'
      +   '<p class="dl-hint">' + escHtml(t.downloadHint) + '</p>'
      + '</section>';

    secs.forEach(function (sec) {
      var body = '';
      if (sec.id === 'sec-tools')        { body = '<p class="sub">' + escHtml(t.toolsDesc) + '</p>' + toolsTableHtml(t); }
      else if (sec.id === 'sec-apis')    { body = apisTableHtml(t); }
      else if (sec.id === 'sec-install') { body = stepsHtml(t); }
      else if (sec.id === 'sec-note')    { body = '<div class="note-box">' + escHtml(t.noteText) + '</div>'; }
      html += '<section id="' + sec.id + '" class="card">'
        + '<div class="card-head"><span class="marker" style="background:' + sec.color + '"></span><h2>' + escHtml(sec.title) + '</h2></div>'
        + '<div class="card-body">' + body + '</div></section>';
    });
    document.getElementById('content').innerHTML = html;

    initScrollSpy();
  }

  function initScrollSpy() {
    var links = document.querySelectorAll('.nav-link');
    var targets = [];
    links.forEach(function (l) {
      var el = document.getElementById(l.getAttribute('data-target'));
      if (el) { targets.push({ link: l, el: el }); }
    });
    function onScroll() {
      var pos = (window.scrollY || document.documentElement.scrollTop) + 120;
      var currentId = '';
      targets.forEach(function (o) { if (pos >= o.el.offsetTop) { currentId = o.el.id; } });
      links.forEach(function (l) {
        if (l.getAttribute('data-target') === currentId) { l.classList.add('active'); }
        else { l.classList.remove('active'); }
      });
    }
    window.removeEventListener('scroll', onScroll);
    window.addEventListener('scroll', onScroll);
    onScroll();
  }

  function changeLang(lang) {
    if (!I18N[lang]) { return; }
    currentLang = lang;
    var url = new URL(window.location);
    url.searchParams.set('lang', lang);
    window.history.replaceState({}, '', url);
    render();
  }

  function toggleSidebar() {
    var sb = document.getElementById('sidebar');
    var bd = document.getElementById('backdrop');
    var open = sb.classList.toggle('open');
    if (open) { bd.classList.add('show'); } else { bd.classList.remove('show'); }
  }

  function onNav() {
    if (window.innerWidth < 1024) { toggleSidebar(); }
  }

  function downloadPack() {
    var bin = atob(ZIP_B64);
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) { bytes[i] = bin.charCodeAt(i); }
    var blob = new Blob([bytes], { type: 'application/zip' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = DATA.zipFilename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 1500);
  }

  buildLangSelect();
  render();